'use strict';

const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = Number(input[0]);
const k = Number(input[1]);
const l = BigInt(input[2]);

const MOD = 998244353n;
const maxN = 2 * n + 1;

function modPow(base, exp) {
    let result = 1n;
    base %= MOD;
    while (exp > 0n) {
        if (exp & 1n) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1n;
    }
    return result;
}

const fact = new Array(maxN + 1).fill(1n);
const invFact = new Array(maxN + 1).fill(1n);

for (let i = 1; i <= maxN; i++) {
    fact[i] = fact[i - 1] * BigInt(i) % MOD;
}

invFact[maxN] = modPow(fact[maxN], MOD - 2n);
for (let i = maxN; i >= 1; i--) {
    invFact[i - 1] = invFact[i] * BigInt(i) % MOD;
}

function combination(a, b) {
    if (b < 0 || b > a) return 0n;
    return fact[a] * invFact[b] % MOD * invFact[a - b] % MOD;
}

let answer = 0n;
let powerOfTwo = modPow(2n, BigInt(k));

for (let j = k; j <= n; j++) {
    const coefficient =
        combination(n, j) * combination(j - 1, k - 1) % MOD;

    const integral =
        powerOfTwo * fact[j] % MOD *
        fact[j] % MOD *
        invFact[2 * j + 1] % MOD;

    const term = coefficient * integral % MOD;

    if ((j - k) % 2 === 0) {
        answer += term;
    } else {
        answer -= term;
    }

    answer %= MOD;
    powerOfTwo = powerOfTwo * 2n % MOD;
}

answer = (answer % MOD + MOD) % MOD;
answer = answer * (l % MOD) % MOD;

console.log(answer.toString());

