'use strict';

const fs = require('fs');
const [n, k, l] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const MOD = 998244353;
const BASE = 1024;

function mulMod(a, b) {
    const ah = Math.floor(a / BASE);
    const al = a - ah * BASE;
    const bh = Math.floor(b / BASE);
    const bl = b - bh * BASE;

    let result = (ah * bh) % MOD;
    result = (result * BASE) % MOD;
    result = (result * BASE) % MOD;
    result += (ah * bl + al * bh) * BASE + al * bl;
    return result % MOD;
}

function powMod(base, exponent) {
    let result = 1;
    while (exponent > 0) {
        if (exponent % 2 === 1) result = mulMod(result, base);
        base = mulMod(base, base);
        exponent = Math.floor(exponent / 2);
    }
    return result;
}

const limit = 2 * n + 1;
const fact = new Float64Array(limit + 1);
const invFact = new Float64Array(limit + 1);

fact[0] = 1;
for (let i = 1; i <= limit; i++) {
    fact[i] = (fact[i - 1] * i) % MOD;
}

invFact[limit] = powMod(fact[limit], MOD - 2);
for (let i = limit; i >= 1; i--) {
    invFact[i - 1] = (invFact[i] * i) % MOD;
}

function binomial(a, b) {
    if (b < 0 || b > a) return 0;
    return mulMod(mulMod(fact[a], invFact[b]), invFact[a - b]);
}

const inverses = new Float64Array(n + 2);
inverses[1] = 1;
for (let i = 2; i <= n + 1; i++) {
    inverses[i] = MOD - mulMod(Math.floor(MOD / i), inverses[MOD % i]);
}

const factorialPair = new Float64Array(2 * n + 1);
for (let x = 0; x <= 2 * n; x++) {
    factorialPair[x] = mulMod(fact[x], fact[2 * n - x]);
}

let m = n - k;
const row = new Float64Array(m + 1);
row[0] = 1;
for (let a = 1; a <= m; a++) {
    row[a] = mulMod(mulMod(row[a - 1], m - a + 1), inverses[a]);
}

let coefficient = mulMod(binomial(n, k), powMod(2, k));
let total = 0;

for (let j = k; j <= n; j++) {
    let sum = 0;

    for (let a = 0; a <= m; a++) {
        sum += mulMod(row[a], factorialPair[j + 2 * a]);
        if (sum >= MOD) sum -= MOD;
    }

    total += mulMod(coefficient, sum);
    if (total >= MOD) total -= MOD;

    if (j < n) {
        for (let a = 1; a < m; a++) {
            let value = row[a] - row[a - 1];
            if (value < 0) value += MOD;
            row[a] = value;
        }

        m--;

        coefficient = mulMod(coefficient, 2 * (n - j));
        coefficient = mulMod(coefficient, inverses[j + 1]);
    }
}

let answer = mulMod(total, invFact[2 * n + 1]);
answer = mulMod(answer, l % MOD);

